/*
 * SEO helpers: absolute URLs and schema.org JSON-LD.
 *
 * The canonical origin comes from `site` in astro.config.mjs
 * (https://aloessential.com, URLs with a trailing slash). Structured data only
 * describes what the page really shows: no Product, Offer, Review or rating
 * markup, since the site sells nothing and publishes no customer reviews.
 */

export const SITE_NAME = "Aloessential";
import { coverShare } from "./images";

/** Default share image (raster, 1200 × 630), generated by tools/generate-og-image.py. */
export const DEFAULT_OG_IMAGE = "/brand/og-default.png";

export interface ShareImage {
  src: string;
  width: number;
  height: number;
  alt?: string;
}

export const DEFAULT_SHARE_IMAGE: ShareImage = { src: DEFAULT_OG_IMAGE, width: 1200, height: 630 };

/**
 * Raster share image for a cover (src/lib/images.ts): Open Graph, Article
 * structured data and Google Discover need a large raster image. SVG covers
 * have a 1200 × 800 JPEG twin; photographs a 1200 px wide 16:9 JPEG.
 */
export function coverShareImage(cover: string, alt?: string): ShareImage {
  return { ...coverShare(cover), alt };
}

export function absoluteUrl(path: string, site: URL | undefined): string {
  if (!site) throw new Error("`site` must be set in astro.config.mjs");
  return new URL(path, site).href;
}

type JsonLd = Record<string, unknown>;

export function organizationLd(site: URL | undefined): JsonLd {
  return {
    "@type": "Organization",
    "@id": absoluteUrl("/#organization", site),
    name: SITE_NAME,
    url: absoluteUrl("/", site),
    logo: absoluteUrl("/brand/icon-720.webp", site),
  };
}

export function websiteLd(site: URL | undefined): JsonLd {
  return {
    "@type": "WebSite",
    "@id": absoluteUrl("/#website", site),
    name: SITE_NAME,
    url: absoluteUrl("/", site),
    inLanguage: "fr-FR",
    publisher: { "@id": absoluteUrl("/#organization", site) },
  };
}

export interface Crumb {
  name: string;
  path: string;
}

export function breadcrumbLd(crumbs: Crumb[], site: URL | undefined): JsonLd {
  return {
    "@type": "BreadcrumbList",
    itemListElement: crumbs.map((c, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: c.name,
      item: absoluteUrl(c.path, site),
    })),
  };
}

export function articleLd(
  a: {
    title: string;
    description: string;
    date: Date;
    cover: string;
    /** Name, caption and description of the cover, when the article provides them. */
    image?: { name?: string; caption?: string; description?: string };
    path: string;
    author: string;
    inLanguage?: string;
  },
  site: URL | undefined,
): JsonLd {
  const image = imageObjectLd(a.cover, a.image ?? {}, site);
  return {
    "@type": "Article",
    headline: a.title,
    description: a.description,
    datePublished: a.date.toISOString(),
    // A plain URL, or an ImageObject when the cover has a name or caption.
    image: Object.keys(image).length > 5 ? image : image.url,
    inLanguage: a.inLanguage ?? "fr-FR",
    mainEntityOfPage: absoluteUrl(a.path, site),
    author: { "@type": "Person", name: a.author, url: absoluteUrl("/equipe/", site) },
    publisher: { "@id": absoluteUrl("/#organization", site) },
  };
}

/** The share raster of a cover as a schema.org ImageObject, with its name, caption and description when given. */
export function imageObjectLd(
  cover: string,
  details: { name?: string; caption?: string; description?: string },
  site: URL | undefined,
): JsonLd {
  const share = coverShareImage(cover);
  const url = absoluteUrl(share.src, site);
  const extra = Object.fromEntries(Object.entries(details).filter(([, v]) => v));
  return { "@type": "ImageObject", url, contentUrl: url, width: share.width, height: share.height, ...extra };
}

/** Wraps nodes in a single @graph document. */
export function graph(nodes: JsonLd[]): string {
  // Escape "<" so content can never close the <script> element.
  return JSON.stringify({ "@context": "https://schema.org", "@graph": nodes }).replace(/</g, "\\u003c");
}
